// Builds reference vectors with the OFFICIAL JS client (@solana-program/token, generated by Codama)
// so the Kotlin output can be checked byte for byte.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import {
  getAddressDecoder, getAddressEncoder, getProgramDerivedAddress, getU64Encoder, getU8Encoder, getUtf8Encoder,
  createNoopSigner, some, none, AccountRole,
} from '@solana/kit';
import * as token from '@solana-program/token';

const out = process.argv[2];
const addr = (i) => getAddressDecoder().decode(new Uint8Array(32).fill(i));
const signer = (i) => createNoopSigner(addr(i));
const hex = (b) => Buffer.from(b).toString('hex');

const A = { source: addr(1), destination: addr(2), mint: addr(3), owner: addr(4), m1: addr(5), m2: addr(6), multisig: addr(7) };

function ix(id, instruction) {
  return {
    id,
    programAddress: instruction.programAddress,
    accounts: instruction.accounts.map((a) => ({
      address: a.address,
      isSigner: a.role === AccountRole.READONLY_SIGNER || a.role === AccountRole.WRITABLE_SIGNER,
      isWritable: a.role === AccountRole.WRITABLE || a.role === AccountRole.WRITABLE_SIGNER,
    })),
    data: hex(instruction.data),
  };
}

const instructions = [
  ix('transfer', token.getTransferInstruction({ source: A.source, destination: A.destination, authority: signer(4), amount: 1_000_000n })),
  ix('transferChecked', token.getTransferCheckedInstruction({ source: A.source, mint: A.mint, destination: A.destination, authority: signer(4), amount: 18_446_744_073_709_551_615n, decimals: 9 })),
  ix('transferCheckedMultisig', token.getTransferCheckedInstruction({ source: A.source, mint: A.mint, destination: A.destination, authority: A.multisig, amount: 42n, decimals: 6, multiSigners: [signer(5), signer(6)] })),
  ix('initializeMintNoFreeze', token.getInitializeMintInstruction({ mint: A.mint, decimals: 6, mintAuthority: A.owner })),
  ix('initializeMintWithFreeze', token.getInitializeMintInstruction({ mint: A.mint, decimals: 0, mintAuthority: A.owner, freezeAuthority: A.m1 })),
  ix('initializeMint2', token.getInitializeMint2Instruction({ mint: A.mint, decimals: 9, mintAuthority: A.owner, freezeAuthority: some(A.m2) })),
  ix('setAuthorityNone', token.getSetAuthorityInstruction({ owned: A.mint, owner: signer(4), authorityType: token.AuthorityType.FreezeAccount, newAuthority: null })),
  ix('setAuthoritySome', token.getSetAuthorityInstruction({ owned: A.source, owner: signer(4), authorityType: token.AuthorityType.CloseAccount, newAuthority: A.m1 })),
  ix('mintTo', token.getMintToInstruction({ mint: A.mint, token: A.destination, mintAuthority: signer(4), amount: 7n })),
  ix('burnChecked', token.getBurnCheckedInstruction({ account: A.source, mint: A.mint, authority: signer(4), amount: 99n, decimals: 2 })),
  ix('approveChecked', token.getApproveCheckedInstruction({ source: A.source, mint: A.mint, delegate: A.m1, owner: signer(4), amount: 5n, decimals: 3 })),
  ix('closeAccount', token.getCloseAccountInstruction({ account: A.source, destination: A.destination, owner: signer(4) })),
  ix('initializeMultisig', token.getInitializeMultisigInstruction({ multisig: A.multisig, m: 2, signers: [A.m1, A.m2] })),
  ix('syncNative', token.getSyncNativeInstruction({ account: A.source })),
  ix('amountToUiAmount', token.getAmountToUiAmountInstruction({ mint: A.mint, amount: 123456789n })),
  ix('uiAmountToAmount', token.getUiAmountToAmountInstruction({ mint: A.mint, uiAmount: '1.2345' })),
  ix('withdrawExcessLamports', token.getWithdrawExcessLamportsInstruction({ source: A.source, destination: A.destination, authority: signer(4) })),
  ix('unwrapLamportsAll', token.getUnwrapLamportsInstruction({ source: A.source, destination: A.destination, authority: signer(4) })),
  ix('unwrapLamportsSome', token.getUnwrapLamportsInstruction({ source: A.source, destination: A.destination, authority: signer(4), amount: 500n })),
  ix('initializeAccount', token.getInitializeAccountInstruction({ account: A.source, mint: A.mint, owner: A.owner })),
  ix('initializeAccount2', token.getInitializeAccount2Instruction({ account: A.source, mint: A.mint, owner: A.owner })),
  ix('initializeAccount3', token.getInitializeAccount3Instruction({ account: A.source, mint: A.mint, owner: A.owner })),
  ix('approve', token.getApproveInstruction({ source: A.source, delegate: A.m1, owner: signer(4), amount: 11n })),
  ix('revokeMultisig', token.getRevokeInstruction({ source: A.source, owner: A.multisig, multiSigners: [signer(5)] })),
  ix('burn', token.getBurnInstruction({ account: A.source, mint: A.mint, authority: signer(4), amount: 3n })),
  ix('freezeAccount', token.getFreezeAccountInstruction({ account: A.source, mint: A.mint, owner: signer(4) })),
  ix('thawAccount', token.getThawAccountInstruction({ account: A.source, mint: A.mint, owner: signer(4) })),
  ix('mintToChecked', token.getMintToCheckedInstruction({ mint: A.mint, token: A.destination, mintAuthority: signer(4), amount: 8n, decimals: 4 })),
  ix('initializeMultisig2', token.getInitializeMultisig2Instruction({ multisig: A.multisig, m: 1, signers: [A.m1, A.m2] })),
  ix('getAccountDataSize', token.getGetAccountDataSizeInstruction({ mint: A.mint })),
  ix('initializeImmutableOwner', token.getInitializeImmutableOwnerInstruction({ account: A.source })),
  // The JS package replaces the generated batch builder with a helper, so we compare the raw data encoder.
  { id: 'batch', programAddress: token.TOKEN_PROGRAM_ADDRESS, accounts: [], data: hex(token.getBatchInstructionDataEncoder().encode({ data: [
    { numberOfAccounts: 3, instructionData: new Uint8Array([3, 1, 2, 3, 4, 5, 6, 7, 8]) },
    { numberOfAccounts: 1, instructionData: new Uint8Array([17]) },
  ] })) },
];

const accounts = [
  { id: 'mint', data: hex(token.getMintEncoder().encode({ mintAuthority: some(A.owner), supply: 1_000_000_000n, decimals: 9, isInitialized: true, freezeAuthority: none() })) },
  { id: 'token', data: hex(token.getTokenEncoder().encode({ mint: A.mint, owner: A.owner, amount: 77n, delegate: some(A.m1), state: token.AccountState.Frozen, isNative: some(2_039_280n), delegatedAmount: 10n, closeAuthority: none() })) },
  { id: 'multisig', data: hex(token.getMultisigEncoder().encode({ m: 2, n: 3, isInitialized: true, signers: Array.from({ length: 11 }, (_, i) => (i < 3 ? addr(10 + i) : addr(0))) })) },
];

// PDAs. Associated token accounts: the official generated JS helper. Squads: Solana Kit's own PDA derivation and
// encoders, fed the seeds of idl/squads.json (the same seeds the devnet-tested hand-written Kotlin used).
const TOKEN_2022 = 'TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb';
const ata = async (id, owner, tokenProgram, mint) => {
  const [address, bump] = await token.findAssociatedTokenPda({ owner, tokenProgram, mint });
  return { id, seeds: { owner, tokenProgram, mint }, address, bump };
};
const squadsIdl = JSON.parse(readFileSync(new URL('../idl/squads.json', import.meta.url), 'utf8'));
const seedEncoders = {
  publicKeyTypeNode: (v) => getAddressEncoder().encode(v),
  u8: (v) => getU8Encoder().encode(v),
  u64: (v) => getU64Encoder().encode(BigInt(v)),
};
const squads = async (id, pdaName, values) => {
  const pda = squadsIdl.program.pdas.find((p) => p.name === pdaName);
  const seeds = pda.seeds.map((s) => {
    if (s.kind === 'constantPdaSeedNode') return getUtf8Encoder().encode(s.value.string);
    return seedEncoders[s.type.kind === 'numberTypeNode' ? s.type.format : s.type.kind](values[s.name]);
  });
  const [address, bump] = await getProgramDerivedAddress({ programAddress: squadsIdl.program.publicKey, seeds });
  return { id, pda: pdaName, seeds: values, address, bump };
};
const S = { multisig: addr(20), createKey: addr(21) };
const pdas = await Promise.all([
  ata('ataToken', A.owner, token.TOKEN_PROGRAM_ADDRESS, A.mint),
  ata('ataToken2022', A.owner, TOKEN_2022, A.mint),
  ata('ataUsdc', addr(9), token.TOKEN_PROGRAM_ADDRESS, 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v'),
  squads('programConfig', 'programConfig', {}),
  squads('multisig', 'multisig', { createKey: S.createKey }),
  squads('vault0', 'vault', { multisig: S.multisig, index: 0 }),
  squads('vault255', 'vault', { multisig: S.multisig, index: 255 }),
  squads('transaction1', 'transaction', { multisig: S.multisig, index: '1' }),
  squads('transactionBig', 'transaction', { multisig: S.multisig, index: '1099511627776' }),
  squads('proposal7', 'proposal', { multisig: S.multisig, transactionIndex: '7' }),
  squads('spendingLimit', 'spendingLimit', { multisig: S.multisig, createKey: S.createKey }),
]);

mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, JSON.stringify({ addresses: A, instructions, accounts, pdas }, null, 2));
console.log(`Wrote ${instructions.length} instruction vectors, ${accounts.length} account vectors and ${pdas.length} PDA vectors to ${out}`);
